<template><section class="builder-panel scenes-panel"><header class="builder-panel__heading"><strong>▧ Overlay Scenes</strong><button @click="$emit('action','add')">＋</button></header><div class="scene-list"><button v-for="scene in scenes" :key="scene.id" :class="{active:scene.id===selectedId}" @click="$emit('select',scene.id)"><span class="scene-thumb" :class="scene.preview.referenceAssetId"></span><strong>{{ scene.name }}</strong><small>{{ scene.widgets.length }} widgets</small><i v-if="scene.isDefault">✓</i></button></div><footer><button @click="$emit('action','duplicate')">▣ Duplicate</button><button @click="$emit('action','rename')">✎ Rename</button><button @click="$emit('action','default')">★ Default</button><button @click="$emit('action','delete')">⌫</button></footer></section></template>
<script setup>defineProps({scenes:Array,selectedId:String});defineEmits(['select','action'])</script>
